<?php
/** Transactional next-action email. Pure renderer; all links require the normal panel session. */
function impActionEscape($s) { return htmlspecialchars((string) $s, ENT_QUOTES, 'UTF-8'); }
function impActionMoney($n) { return '$' . number_format((float) $n, 0, ',', '.') . ' CLP'; }

function impActionEmail($data) {
    $e = 'impActionEscape';
    $tasks = $data['tasks'];
    $main = $tasks[0];
    $client = $data['audience'] === 'client';
    $payment = $main['kind'] === 'payment';
    $order = $data['order_number'];
    $name = $data['name'];
    $greeting = trim((string) $name) === '' ? 'Hola,' : 'Hola ' . $name . ',';
    $boat = $data['boat'];
    $approved = $client && !empty($data['inspection_approved']);
    $title = $payment ? 'Tu próximo paso: ' . $main['title'] : $main['title'];
    $subject = ($client ? 'Tu próximo paso' : 'Acción interna pendiente') . ' · ' . $order . ' · ' . $main['title'];
    $intro = $client
        ? ($approved ? 'Ya recibí tu aprobación de la inspección. ' : '') . 'Para avanzar con la compra e importación de tu lancha, ' . ($payment ? 'tienes este pago pendiente.' : 'necesito que revises el siguiente paso.')
        : 'Hay una revisión pendiente del equipo para que esta operación pueda avanzar. Revisa los antecedentes antes de registrar cualquier cambio.';
    if ($client && $payment && !empty($data['correct_payment_notice'])) {
        $subject='Corrección · '.$order.' · Corresponde el Pago 2';
        $intro='Te escribo para corregir mi correo anterior: el Pago 1 ya está realizado y no debes volver a pagarlo. Disculpa la confusión. Con tu aprobación de la inspección registrada, ahora corresponde el Pago 2 para avanzar con la compra. Se mantienen los precios previamente acordados.';
    }
    $rows = '';
    foreach (array_slice($tasks, 1) as $task) {
        $rows .= '<tr><td style="padding:14px 0;border-bottom:1px solid #e2e8f0"><strong style="font-size:15px;color:#102f3d">' . $e($task['title']) . '</strong><p style="margin:6px 0 10px;font-size:13px;line-height:1.6;color:#526b78">' . $e($task['detail']) . '</p><a href="' . $e($task['url']) . '" style="font-size:14px;font-weight:bold;color:#087e91;text-decoration:underline">' . $e($task['button']) . ' &rarr;</a></td></tr>';
    }
    $amount = $payment ? '<p style="margin:16px 0 4px;font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#526b78">Monto de la solicitud vigente</p><p class="amount" style="margin:0 0 18px;font-size:36px;line-height:1.2;font-weight:700;color:#102f3d">' . $e(impActionMoney($main['amount_clp'])) . '</p>' : '';
    $paymentHelp = $payment ? '<tr><td class="pad" style="padding:0 32px 24px"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#f1f7f8;border:1px solid #d9e9ec;border-radius:12px"><tr><td style="padding:18px"><strong style="font-size:14px;color:#102f3d">Transferencia con Global66</strong><p style="margin:7px 0 0;font-size:13px;line-height:1.7;color:#526b78">En tu panel puedes elegir transferencia y copiar los datos bancarios. Después de transferir, adjunta el comprobante en el mismo pago e indica el monto y la referencia para que pueda conciliarlo.</p><p style="margin:9px 0 0;font-size:13px;line-height:1.7;color:#526b78">Si ya transferiste, <strong>no vuelvas a pagar</strong>. Adjunta el comprobante en el panel. También puedes enviármelo a <a style="color:#087e91" href="mailto:contacto@imporlan.cl">contacto@imporlan.cl</a> o por <a style="color:#087e91" href="https://wa.me/56940211459">WhatsApp</a>, indicando ' . $e($order) . ', para validar el pago.</p></td></tr></table></td></tr>' : '';
    $more = $rows === '' ? '' : '<tr><td class="pad" style="padding:0 32px 24px"><p style="margin:0;font-size:11px;font-weight:bold;letter-spacing:1px;color:#526b78;text-transform:uppercase">También queda pendiente</p><table role="presentation" width="100%" cellspacing="0" cellpadding="0">' . $rows . '</table></td></tr>';
    $signature = $client ? '<p style="margin:0 0 8px;font-size:14px;color:#102f3d">Si necesitas ayuda, responde este correo. Estoy para acompañarte en el proceso.</p><img src="cid:imporlan-signature-jp" alt="Juan Pablo · Imporlan" width="280" style="display:block;max-width:100%;height:auto;margin:14px 0 0"><p style="margin:8px 0 0;font-size:12px;color:#526b78">Juan Pablo · Imporlan<br>contacto@imporlan.cl</p>' : '<p style="margin:0;font-size:13px;color:#526b78">Seguimiento interno · Imporlan<br>Este aviso no publica precios, no aprueba compras y no crea cobros.</p>';
    $html = '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>' . $e($subject) . '</title><style>@media(max-width:620px){.outer{padding:12px 8px!important}.pad{padding-left:20px!important;padding-right:20px!important}.hero-title{font-size:29px!important}.amount{font-size:30px!important}.cta{display:block!important;text-align:center!important}}</style></head><body style="margin:0;padding:0;background:#edf3f5;font-family:Arial,Helvetica,sans-serif;color:#102f3d"><div style="display:none;font-size:1px;line-height:1px;max-height:0;overflow:hidden;opacity:0">' . $e($main['detail']) . '</div><table role="presentation" width="100%" cellspacing="0" cellpadding="0"><tr><td class="outer" align="center" style="padding:28px 12px"><table role="presentation" width="600" cellspacing="0" cellpadding="0" style="width:100%;max-width:600px;background:white;border:1px solid #dce7eb;border-radius:18px;overflow:hidden"><tr><td class="pad" style="padding:28px 32px;background:#102f3d;border-bottom:5px solid #2cb6c2"><p style="margin:0 0 8px;color:#fff;font-size:29px;font-weight:bold;letter-spacing:4px">IMPORLAN<span style="color:#2cb6c2">.</span></p><p style="margin:0;color:#b8d4dc;font-size:11px;letter-spacing:2px;text-transform:uppercase">Compra e importación · seguimiento</p></td></tr><tr><td class="pad" style="padding:30px 32px 22px"><p style="margin:0 0 12px;font-size:11px;letter-spacing:1px;font-weight:bold;color:#087e91">' . $e($order) . ' · ' . ($client ? 'TU SIGUIENTE ACCIÓN' : 'REVISIÓN DEL EQUIPO') . '</p><h1 class="hero-title" style="margin:0 0 14px;font-size:34px;line-height:1.15;letter-spacing:-1px;color:#102f3d">' . $e($title) . '</h1><p style="margin:0 0 18px;color:#526b78;font-size:15px;line-height:1.5">' . $e($boat) . '</p>' . ($approved ? '<p style="margin:0 0 18px;font-size:12px;font-weight:bold;color:#167450">&#10003; Tu aprobación de la inspección ya está registrada</p>' : '') . '<p style="margin:0 0 10px;font-size:16px;color:#102f3d">' . $e($greeting) . '</p><p style="margin:0;font-size:15px;line-height:1.8;color:#526b78">' . $e($intro) . '</p></td></tr><tr><td class="pad" style="padding:0 32px 24px"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="border:1px solid #a8d9df;background:#f0fbfc;border-radius:12px"><tr><td style="padding:22px"><p style="margin:0;font-size:15px;font-weight:bold;color:#102f3d">' . $e($main['title']) . '</p><p style="margin:8px 0 0;font-size:14px;line-height:1.7;color:#526b78">' . $e($main['detail']) . '</p>' . $amount . '<table role="presentation" cellspacing="0" cellpadding="0" style="margin-top:18px"><tr><td bgcolor="#087e91" style="border-radius:8px"><a class="cta" href="' . $e($main['url']) . '" style="display:inline-block;padding:15px 22px;font-size:15px;font-weight:bold;color:#fff;text-decoration:none;border:1px solid #087e91;border-radius:8px">' . $e($main['button']) . ' &rarr;</a></td></tr></table><p style="margin:12px 0 0;font-size:12px;line-height:1.6;color:#526b78">El botón abre tu panel seguro. Inicia sesión con tu cuenta para continuar.</p></td></tr></table></td></tr>' . $paymentHelp . $more . '<tr><td class="pad" style="padding:2px 32px 26px">' . $signature . '</td></tr><tr><td class="pad" style="padding:18px 32px;background:#f7fafb;border-top:1px solid #e2e8f0"><p style="margin:0;font-size:11px;line-height:1.7;color:#667e89">Aviso del proceso ' . $e($order) . '. Los recordatorios se detienen cuando el sistema registra que la acción está resuelta. Si acabas de completarla, no necesitas repetirla.</p><p style="margin:10px 0 0;font-size:11px;line-height:1.7;color:#667e89">¿No se abre el botón? Copia este enlace en tu navegador:<br><a style="color:#087e91;word-break:break-all" href="' . $e($main['url']) . '">' . $e($main['url']) . '</a></p></td></tr></table><p style="margin:18px 0 0;font-size:11px;color:#667e89">Imporlan · Tu lancha, paso a paso.</p></td></tr></table></body></html>';
    $text = "$greeting\n\n$intro\n\n$boat · $order\n\n";
    foreach ($tasks as $task) $text .= $task['title'] . (!empty($task['amount_clp']) ? ' · ' . impActionMoney($task['amount_clp']) : '') . "\n" . $task['detail'] . "\n" . $task['button'] . ': ' . $task['url'] . "\n\n";
    if ($payment) $text .= "Puedes transferir con Global66 usando los datos del panel. Adjunta el comprobante al pago con su monto y referencia. Si ya transferiste, no vuelvas a pagar. También puedes enviar el comprobante a contacto@imporlan.cl o por WhatsApp, indicando $order.\n\n";
    $text .= $client ? "Juan Pablo · Imporlan\ncontacto@imporlan.cl\n" : "Seguimiento interno · Imporlan\n";
    return ['subject' => $subject, 'html' => $html, 'text' => $text];
}
